assign MMR_Trdstramdata_muxed = {
    MMR_Trdstramdata_F_Trdstramdata_Data_muxed
};
assign MMR_ScratchLo = {
    MMR_ScratchLo_F_Data
};
logic [31:0] MMR_ScratchLo_muxed;
assign MMR_ScratchLo_muxed = {
